const now = Date.now();
const todayStr = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Warsaw' }).format(new Date(now));
return [{ json: { todayStr, dueGt: now - 48*3600*1000, dueLt: now + 48*3600*1000, now } }];

const TASKS = ($('Fetch Due Tasks').first().json.tasks) || [];
const lastPage = $('Fetch Due Tasks').first().json.last_page;
const todayStr = $('Compute Window').first().json.todayStr;
const TELEMETRY = new Set(['869dj2z2c']);
const AI_FIELD = '088d66e2-6095-4604-b70d-e50ebb085ae2';
const IMPACT_FIELD = '55c7ff79-1857-41e6-87b4-bd46678e1470';
const IMPACT_VALID = ['Niski','Średni','Wysoki','Krytycznie ważne'];
const tzDate = (ms) => new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Warsaw'}).format(new Date(Number(ms)));
function optName(cf){ if(!cf) return ''; const v=cf.value; if(v===undefined||v===null||v==='') return ''; const opts=(cf.type_config&&cf.type_config.options)||[]; const m=opts.find(o=>o.id===v)||opts.find(o=>String(o.orderindex)===String(v)); return m?m.name:''; }
const counts={found:TASKS.length,wrong_day:0,no_due:0,not_tak:0,assignee_count:0,closed_done:0,telemetry:0,candidates:0};
const candidates=[];
for(const t of TASKS){
  if(TELEMETRY.has(t.id)){counts.telemetry++;continue;}
  if(!t.due_date){counts.no_due++;continue;}
  if(tzDate(t.due_date)!==todayStr){counts.wrong_day++;continue;}
  const cfs=t.custom_fields||[];
  if(optName(cfs.find(f=>f.id===AI_FIELD))!=='Tak'){counts.not_tak++;continue;}
  const as=t.assignees||[];
  if(as.length!==1){counts.assignee_count++;continue;}
  const st=(t.status&&typeof t.status==='object')?(t.status.type||''):'';
  if(st==='closed'||st==='done'){counts.closed_done++;continue;}
  let impact=optName(cfs.find(f=>f.id===IMPACT_FIELD));
  if(IMPACT_VALID.indexOf(impact)===-1) impact='Średni';
  candidates.push({taskId:t.id,taskName:t.name||'',assigneeId:String(as[0].id),assigneeUsername:as[0].username||'',impact});
}
counts.candidates=candidates.length;
return [{json:{candidates,counts,last_page:lastPage}}];

const gate=$('Gate Tasks').first().json;
const candidates=gate.candidates||[];
const counts=Object.assign({},gate.counts);
const rows=$('Dedup Query').all().map(i=>i.json).filter(r=>r&&r.clickup_task_id);
const matched=new Set(rows.map(r=>String(r.clickup_task_id)));
const survivors=candidates.filter(c=>!matched.has(String(c.taskId)));
counts.already_actioned=candidates.length-survivors.length;
counts.enqueued=survivors.length;
counts.last_page=gate.last_page;
const out=survivors.map(c=>({json:Object.assign({_kind:'task'},c)}));
out.push({json:{_kind:'summary',counts}});
return out;

const t=$json;
const job={ task_id:t.taskId, caller_user_id:t.assigneeId, impact:t.impact, invocation_type:'due_date', enqueued_at:new Date().toISOString(), payload:{ reviewer_user_id:t.assigneeId, caller_username:t.assigneeUsername||'', triggered_by:'due_date_daily', invocation_type:'autonomous', triggering_comment_id:'', triggering_comment_text:'' } };
return { json: Object.assign({}, t, { job }) };

const c=$json.counts||{};
const trunc = c.last_page===false;
const lines=[
 `Producent due-date (dzienny): znaleziono ${c.found??0} zadań w oknie czasowym.`,
 `Zakwalifikowano: ${c.candidates??0}; już obsłużone dziś (pominięto): ${c.already_actioned??0}; uruchomiono: ${c.enqueued??0}.`,
 `Pominięto — zły dzień: ${c.wrong_day??0}, brak terminu: ${c.no_due??0}, nie dla AI: ${c.not_tak??0}, przypisani≠1: ${c.assignee_count??0}, zamknięte/gotowe: ${c.closed_done??0}, telemetria: ${c.telemetry??0}.`
];
if(trunc) lines.push('UWAGA: wyniki ClickUp obcięte (last_page=false) — możliwe pominięte zadania.');
return { json:{ severity: trunc?'WARN':'INFO', source:'due-date-producer', message: lines.join(' '), details: JSON.stringify(c) } };
